#!/usr/bin/env bash
set -euo pipefail

# Fase 5 -- Identidad de marca BigMat + rediseno de App Conductor
# (estilo Bringg), primera de las 2 fases en que se dividio el pedido de
# rediseño visual completo (la otra, reestructurar el Planificador en vista
# partida + Gantt, queda pendiente y se entregara aparte cuando se pida).
#
# Que cambia:
#  1) Colores corporativos reales de BigMat en las 4 apps (Backoffice, Portal
#     Transportista, App Conductor, Portal Cliente): azul #03418c y rojo
#     #e31d1a, extraidos por muestreo de pixeles del logotipo real (no a ojo).
#     Mismo mecanismo ya usado en las Fases 1-4: se sustituye la paleta bajo
#     los nombres de siempre (brand-*, red-*) en cada tailwind.config.js, asi
#     que NINGUN fichero que ya usaba esas clases necesita tocarse.
#  2) Logotipo BigMat (dos variantes: completo y solo texto/wordmark, ambos
#     con fondo transparente) anadido en la cabecera de las 4 apps y en las 4
#     pantallas de login -- Backoffice, Portal Transportista, App Conductor y
#     Portal Cliente (incluida la consulta publica de seguimiento).
#  3) App Conductor, pantalla de parada: la zona de accion (antes dos botones
#     de ancho completo, 'Confirmar entrega' y 'Incidencia / Retorno') pasa a
#     una barra inferior fija con iconos Foto / Firma / Incidencia + un boton
#     grande 'Completar entrega', igual que en Bringg. Los iconos Foto y Firma
#     NO abren nada nuevo: hacen scroll suave hasta el mismo formulario de
#     siempre (foto/firma ya estaban ahi, en linea). A proposito NO se anaden
#     iconos de 'Formularios' ni 'Escanear' -- en la referencia de Bringg
#     existen, pero esta app no tiene formularios configurables ni escaneo de
#     codigos, y anadir esos botones seria una funcion decorativa sin nada
#     real detras. Nada del flujo de entrega (que datos se guardan, que
#     endpoints se llaman) cambia -- es solo reordenar visualmente lo que ya
#     habia.
#
# Sin cambios de esquema ni de backend -- no hace falta 'prisma generate' ni
# reiniciar el backend, solo recompilar/servir las 4 apps de frontend.
# Ejecutar desde la raiz del repo tms-production.

REPO_ROOT="$(pwd)"

TMP_ASSETS="$(mktemp -d)"
trap 'rm -rf "$TMP_ASSETS"' EXIT

base64 -d > "$TMP_ASSETS/bigmat-logo.png" <<'B64EOF'
